from functools import wraps


def retry(n, exceptions):
    def outer_wrapper(f):
        @wraps(f)
        def inner_wrapper(*args, **kwargs):
            exc = None
            for i in range(n + 1):
                try:
                    return f(*args, **kwargs)
                except exceptions as e:
                    exc = e
            raise exc
        return inner_wrapper
    return outer_wrapper
